package app.streamnest;
import android.app.*;import android.content.*;import java.io.*;import org.json.*;import java.util.*;import org.libtorrent4j.*;
final class TvEpisodeRegression {
 static void verifyReads(Context c)throws Exception{
  TorrentEngine e=new TorrentEngine();e.video=new File(c.getCacheDir(),"range-proof.bin");e.size=12288;e.pieceLength=4096;byte[] bytes=new byte[12288];Arrays.fill(bytes,(byte)37);java.nio.file.Files.write(e.video.toPath(),bytes);
  TorrentEngine.PieceStream read=e.new PieceStream(4096,8191);java.util.concurrent.atomic.AtomicInteger count=new java.util.concurrent.atomic.AtomicInteger(-1);Thread t=new Thread(()->{try{count.set(read.read(new byte[4096],0,4096));}catch(IOException ignored){} });t.start();WorkerShutdownRegression.waitFor(()->e.ranges.snapshot().optString("rangeState").equals("waiting"),2000,"Missing wait measurement");HomeRegression.check(count.get()==-1,"Unverified piece was served");e.available.finished(1);t.join(3000);HomeRegression.check(count.get()==4096&&e.ranges.snapshot().optLong("rangeServedBytes")==4096,"Verified range was not delivered/measured");read.close();
  TorrentEngine.PieceStream pending=e.new PieceStream(8192,12287);Thread waiting=new Thread(()->{try{pending.read(new byte[100],0,100);}catch(IOException ignored){}});waiting.start();WorkerShutdownRegression.waitFor(()->e.ranges.snapshot().optString("rangeState").equals("waiting"),2000,"Second range did not wait");pending.close();waiting.join(2000);HomeRegression.check(!waiting.isAlive(),"Closed read kept waiting");e.close();
 }
 static void freshSources(Context c)throws Exception{
  List<Catalog.Source> sources=EpisodeDiscovery.find("tt3581920",new JSONObject().put("season",1).put("episode",3),"The Last of Us");List<Catalog.Source> attempts=AlternateEpisodes.attempts(sources,"Auto",false);HomeRegression.check(!attempts.isEmpty(),"Fresh source lookup returned no candidates");JSONArray rows=new JSONArray();for(Catalog.Source source:attempts)rows.put(new JSONObject().put("quality",PlaybackPlan.episodeQuality(source)).put("url",source.url).put("seed",source.seeds).put("file",source.filename).put("fileIndex",source.fileIndex).put("title",source.release));java.nio.file.Files.write(new File(c.getCacheDir(),"projector-sources.json").toPath(),rows.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8));
 }
 static void verifyMembers(Instrumentation test)throws Exception{
  Context c=test.getTargetContext();verifyReads(c);File dir=new File(c.getCacheDir(),"clover121");File[] files=dir.listFiles((d,n)->n.endsWith(".torrent"));HomeRegression.check(files!=null&&files.length>=3,"Missing real torrent metadata fixtures");int accepted=0;
  for(File file:files){TorrentInfo info=new TorrentInfo(java.nio.file.Files.readAllBytes(file.toPath()));try{HomeRegression.check(info.isValid(),"Invalid torrent fixture");FileStorage storage=info.files();List<String> paths=new ArrayList<>();List<Long> sizes=new ArrayList<>();for(int i=0;i<storage.numFiles();i++){paths.add(storage.filePath(i));sizes.add(storage.fileSize(i));}List<Integer> matches=new ArrayList<>();for(int i=0;i<paths.size();i++)if(EpisodeFiles.video(paths.get(i))&&EpisodeFiles.matches(paths.get(i),1,121,121))matches.add(i);HomeRegression.check(matches.size()==1,"Real pack did not uniquely identify episode 121");int index=matches.get(0);HomeRegression.check(EpisodeFiles.select(paths,sizes,index,new File(paths.get(index).replace('\\','/')).getName(),true,1,121,121)==index,"Exact member mismatch");boolean rejected=false;try{EpisodeFiles.select(paths,sizes,index,"",true,1,122,122);}catch(IOException expected){rejected=true;}HomeRegression.check(rejected,"Wrong episode accepted");accepted++;}finally{info.swig().delete();}}
  android.util.Log.i("StreamNestVerification","PASS: "+accepted+" real Black Clover packs select121 and reject122");freshSources(c);
 }
}
